    private record IndexedBlendState(
        boolean enabled,
        int srcRgb,
        int dstRgb,
        int srcAlpha,
        int dstAlpha
    ) {
        private String cacheKey() {
            return enabled
                + ":" + srcRgb
                + ":" + dstRgb
                + ":" + srcAlpha
                + ":" + dstAlpha;
        }
    }

