    private static final class LegacyTextureFormatInfo {
        private final int vkFormat;
        private final int pixelBytes;
        private final int unpackPixelBytes;
        private final int aspectMask;
        private final boolean expandRgbToRgba;

        private LegacyTextureFormatInfo(int vkFormat, int pixelBytes, int aspectMask) {
            this(vkFormat, pixelBytes, pixelBytes, aspectMask, false);
        }

        private LegacyTextureFormatInfo(
            int vkFormat,
            int pixelBytes,
            int unpackPixelBytes,
            int aspectMask,
            boolean expandRgbToRgba
        ) {
            this.vkFormat = vkFormat;
            this.pixelBytes = pixelBytes;
            this.unpackPixelBytes = unpackPixelBytes;
            this.aspectMask = aspectMask;
            this.expandRgbToRgba = expandRgbToRgba;
        }

        private static LegacyTextureFormatInfo resolve(int internalFormat, int format, int type) {
            if (internalFormat == VulkanicAPI.GL_DEPTH_STENCIL
                || internalFormat == VulkanicAPI.GL_DEPTH24_STENCIL8
                || (format == VulkanicAPI.GL_DEPTH_STENCIL && type == VulkanicAPI.GL_UNSIGNED_INT_24_8)) {
                return new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_D24_UNORM_S8_UINT,
                    4,
                    VK10.VK_IMAGE_ASPECT_DEPTH_BIT | VK10.VK_IMAGE_ASPECT_STENCIL_BIT
                );
            }

            if (internalFormat == VulkanicAPI.GL_DEPTH32F_STENCIL8
                || (format == VulkanicAPI.GL_DEPTH_STENCIL
                    && type == VulkanicAPI.GL_FLOAT_32_UNSIGNED_INT_24_8_REV)) {
                return new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_D32_SFLOAT_S8_UINT,
                    8,
                    VK10.VK_IMAGE_ASPECT_DEPTH_BIT | VK10.VK_IMAGE_ASPECT_STENCIL_BIT
                );
            }

            if (internalFormat == VulkanicAPI.GL_DEPTH_COMPONENT
                || internalFormat == VulkanicAPI.GL_DEPTH_COMPONENT16
                || internalFormat == VulkanicAPI.GL_DEPTH_COMPONENT24
                || internalFormat == VulkanicAPI.GL_DEPTH_COMPONENT32
                || internalFormat == VulkanicAPI.GL_DEPTH_COMPONENT32F
                || format == VulkanicAPI.GL_DEPTH_COMPONENT) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_D32_SFLOAT, 4, VK10.VK_IMAGE_ASPECT_DEPTH_BIT);
            }

            if ((internalFormat == VulkanicAPI.GL_R8I || format == VulkanicAPI.GL_RED_INTEGER)
                && type == VulkanicAPI.GL_BYTE) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_R8_SINT, 1, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if (internalFormat == VulkanicAPI.GL_R16F
                || (format == VulkanicAPI.GL_RED && type == VulkanicAPI.GL_HALF_FLOAT)) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_R16_SFLOAT, 2, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if (internalFormat == VulkanicAPI.GL_R32F
                && format == VulkanicAPI.GL_RED
                && type == VulkanicAPI.GL_FLOAT) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_R32_SFLOAT, 4, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if (internalFormat == VulkanicAPI.GL_RGBA16F
                || (format == VulkanicAPI.GL_RGBA && type == VulkanicAPI.GL_HALF_FLOAT)) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_R16G16B16A16_SFLOAT, 8, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if ((internalFormat == VulkanicAPI.GL_RGBA16 || internalFormat == VulkanicAPI.GL_RGBA)
                && (type == VulkanicAPI.GL_UNSIGNED_SHORT_4_4_4_4
                || type == VulkanicAPI.GL_UNSIGNED_SHORT_4_4_4_4_REV)) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_R4G4B4A4_UNORM_PACK16, 2, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if ((format == VulkanicAPI.GL_BGRA || internalFormat == VulkanicAPI.GL_BGRA)
                && type == VulkanicAPI.GL_UNSIGNED_BYTE) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_B8G8R8A8_UNORM, 4, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if ((format == VulkanicAPI.GL_RGBA || internalFormat == VulkanicAPI.GL_RGBA8 || internalFormat == VulkanicAPI.GL_RGBA16)
                && type == VulkanicAPI.GL_UNSIGNED_BYTE) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_R8G8B8A8_UNORM, 4, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if (format == VulkanicAPI.GL_RED && type == VulkanicAPI.GL_UNSIGNED_BYTE) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_R8_UNORM, 1, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if (format == GL_LUMINANCE && type == VulkanicAPI.GL_UNSIGNED_BYTE) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_R8_UNORM, 1, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if (format == GL_LUMINANCE_ALPHA && type == VulkanicAPI.GL_UNSIGNED_BYTE) {
                return new LegacyTextureFormatInfo(VK10.VK_FORMAT_R8G8_UNORM, 2, VK10.VK_IMAGE_ASPECT_COLOR_BIT);
            }

            if (format == VulkanicAPI.GL_RGB && type == VulkanicAPI.GL_UNSIGNED_BYTE) {
                // Normalize RGB8 uploads to RGBA8 to avoid fragile 24-bit legacy image allocations.
                return new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_R8G8B8A8_UNORM,
                    4,
                    3,
                    VK10.VK_IMAGE_ASPECT_COLOR_BIT,
                    true
                );
            }

            throw new IllegalArgumentException(
                "Unsupported legacy texture upload format combination: internalFormat=" + internalFormat
                    + ", format=" + format + ", type=" + type);
        }

        private static LegacyTextureFormatInfo resolveStorage(int internalFormat, int format, int type) {
            if (internalFormat == VulkanicAPI.GL_DEPTH_STENCIL
                || internalFormat == VulkanicAPI.GL_DEPTH24_STENCIL8
                || internalFormat == VulkanicAPI.GL_DEPTH32F_STENCIL8) {
                return resolve(internalFormat, format, type);
            }

            if ((format == VulkanicAPI.GL_BGRA || internalFormat == VulkanicAPI.GL_BGRA)
                && type == VulkanicAPI.GL_UNSIGNED_BYTE) {
                return new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_B8G8R8A8_UNORM,
                    4,
                    VK10.VK_IMAGE_ASPECT_COLOR_BIT
                );
            }

            LegacyTextureFormatInfo sizedFormat = switch (internalFormat) {
                case VulkanicAPI.GL_R8 -> new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_R8_UNORM,
                    1,
                    VK10.VK_IMAGE_ASPECT_COLOR_BIT
                );
                case VulkanicAPI.GL_R8UI -> new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_R8_UINT,
                    1,
                    VK10.VK_IMAGE_ASPECT_COLOR_BIT
                );
                case VulkanicAPI.GL_RGBA8 -> new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_R8G8B8A8_UNORM,
                    4,
                    VK10.VK_IMAGE_ASPECT_COLOR_BIT
                );
                case VulkanicAPI.GL_RGBA8_SNORM -> new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_R8G8B8A8_SNORM,
                    4,
                    VK10.VK_IMAGE_ASPECT_COLOR_BIT
                );
                case VulkanicAPI.GL_R32F -> new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_R32_SFLOAT,
                    4,
                    VK10.VK_IMAGE_ASPECT_COLOR_BIT
                );
                case VulkanicAPI.GL_RGBA16F -> new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_R16G16B16A16_SFLOAT,
                    8,
                    VK10.VK_IMAGE_ASPECT_COLOR_BIT
                );
                case VulkanicAPI.GL_R11F_G11F_B10F -> new LegacyTextureFormatInfo(
                    VK10.VK_FORMAT_B10G11R11_UFLOAT_PACK32,
                    4,
                    VK10.VK_IMAGE_ASPECT_COLOR_BIT
                );
                default -> null;
            };

            return sizedFormat != null ? sizedFormat : resolve(internalFormat, format, type);
        }
    }

    /**
     * Vulkan-native handle for a compiled graphics pipeline.
     *
     * <p>Wraps a {@code VkPipeline}, its {@code VkPipelineLayout}, and associated
     * {@code VkDescriptorSetLayout} handles.  All are destroyed deterministically when
     * {@link #close()} is called.</p>
     */
    private static final class VulkanPipelineHandle implements PipelineHandle {
        private final long vkPipelineHandle;
        private final long vkPipelineLayoutHandle;
        private final long[] vkDescriptorSetLayoutHandles;
        private final VulkanRenderPassCompatibilityKey renderPassCompatibilityKey;
        /** Number of resource bindings in the DSL this pipeline was compiled with. */
        private final int resourceBindingCount;
        private final NativeSpine spine;
        private volatile boolean closed;

        private VulkanPipelineHandle(
            long vkPipelineHandle,
            long vkPipelineLayoutHandle,
            long[] vkDescriptorSetLayoutHandles,
            VulkanRenderPassCompatibilityKey renderPassCompatibilityKey,
            int resourceBindingCount,
            NativeSpine spine
        ) {
            this.vkPipelineHandle = vkPipelineHandle;
            this.vkPipelineLayoutHandle = vkPipelineLayoutHandle;
            this.vkDescriptorSetLayoutHandles = vkDescriptorSetLayoutHandles.clone();
            this.renderPassCompatibilityKey = Objects.requireNonNull(
                renderPassCompatibilityKey,
                "renderPassCompatibilityKey must not be null"
            );
            this.resourceBindingCount = resourceBindingCount;
            this.spine = Objects.requireNonNull(spine, "spine must not be null");
        }

        /** Returns the native {@code VkPipeline} handle for command-buffer binding. */
        long getVkPipelineHandle() {
            return vkPipelineHandle;
        }

        /** Returns the native {@code VkPipelineLayout} handle for descriptor set binding. */
        long getVkPipelineLayoutHandle() {
            return vkPipelineLayoutHandle;
        }

        /** Returns the native {@code VkDescriptorSetLayout} handle used by this pipeline. */
        long getVkDescriptorSetLayoutHandle() {
            return vkDescriptorSetLayoutHandles.length == 0 ? VK10.VK_NULL_HANDLE : vkDescriptorSetLayoutHandles[0];
        }

        long[] getVkDescriptorSetLayoutHandles() {
            return vkDescriptorSetLayoutHandles.clone();
        }

        VulkanRenderPassCompatibilityKey getRenderPassCompatibilityKey() {
            return renderPassCompatibilityKey;
        }

        /**
         * Returns the number of resource bindings in the descriptor set layout this pipeline
         * was compiled with. Used to detect partial-write mismatches at draw time.
         */
        int getResourceBindingCount() {
            return resourceBindingCount;
        }

        @Override
        public boolean isValid() {
            return !closed && vkPipelineHandle != VK10.VK_NULL_HANDLE;
        }

        @Override
        public void close() {
            if (closed) return;
            closed = true;
            spine.destroyVulkanPipeline(vkPipelineHandle, vkPipelineLayoutHandle, vkDescriptorSetLayoutHandles);
        }

        @Override
        public String toString() {
            return "VulkanPipelineHandle{valid=" + isValid() + ", pipeline=0x"
                + Long.toHexString(vkPipelineHandle)
                + ", renderPassCompatibility=" + renderPassCompatibilityKey
                + "}";
        }
    }

    public PipelineHandle createPipeline(PipelineDescriptor descriptor) {
        if (descriptor == null) {
            throw new IllegalArgumentException("descriptor must not be null");
        }
        descriptor = VulkanShaderVariantPlanner.withCompatibilityVertexInputState(descriptor);
        ensureNativeReady("createPipeline");
        NativeSpine spine = nativeSpine;
        if (spine == null) {
            throw new IllegalStateException("Native Vulkan spine is unavailable after readiness check.");
        }

        // Vulkan pipeline creation requires precompiled SPIR-V shader modules.
        List<VulkanicSpirvModule> spirvModules = descriptor.getSpirvModules();
        if (spirvModules.isEmpty()) {
            throw new IllegalArgumentException(
                "Vulkan pipeline creation requires precompiled SPIR-V shader modules attached to the "
                + "PipelineDescriptor. Use PipelineDescriptor.fromPortableStateAndSpirvModules(...) "
                + "or PipelineDescriptor.fromRenderPipelineAndSpirvModules(...) to provide SPIR-V "
                + "bytecode for both vertex and fragment stages.");
        }

        VulkanicSpirvModule vertModule = null;
        VulkanicSpirvModule fragModule = null;
        for (VulkanicSpirvModule module : spirvModules) {
            if (module.stage() == VulkanicShaderStage.VERTEX) {
                vertModule = module;
            } else if (module.stage() == VulkanicShaderStage.FRAGMENT) {
                fragModule = module;
            }
        }
        if (vertModule == null) {
            throw new IllegalArgumentException(
                "Vulkan pipeline creation requires a VERTEX stage SPIR-V module in the descriptor.");
        }
        if (fragModule == null) {
            throw new IllegalArgumentException(
                "Vulkan pipeline creation requires a FRAGMENT stage SPIR-V module in the descriptor.");
        }

        // Create transient shader modules, create the pipeline, then immediately destroy the modules
        // (valid per Vulkan spec: VkPipeline owns its compiled shader code after creation).
        long vertModuleHandle = spine.createShaderModule(vertModule);
        long fragModuleHandle = spine.createShaderModule(fragModule);
        try {
            return spine.createVulkanPipeline(
                descriptor,
                vertModuleHandle,
                fragModuleHandle,
                defaultRenderPassCompatibilityKey(),
                null
            );
        } finally {
            spine.destroyShaderModule(vertModuleHandle);
            spine.destroyShaderModule(fragModuleHandle);
        }
    }

    public PipelineHandle createPipeline(PipelineDescriptor descriptor, int framebuffer) {
        if (descriptor == null) {
            throw new IllegalArgumentException("descriptor must not be null");
        }
        return createPipeline(
            descriptor,
            VulkanRenderTargetPlan.framebuffer(
                () -> "Pipeline-compatible framebuffer target",
                resolveFramebufferTargets(framebuffer)
            )
        );
    }

    public PipelineHandle createPipeline(PipelineDescriptor descriptor, VulkanicRenderTargetDescriptor renderTarget) {
        if (descriptor == null) {
            throw new IllegalArgumentException("descriptor must not be null");
        }
        return createPipeline(descriptor, resolveRenderTargetDescriptorPlan(renderTarget));
    }

    private PipelineHandle createPipeline(PipelineDescriptor descriptor, ResolvedFramebufferTargets targets) {
        return createPipeline(descriptor, VulkanRenderTargetPlan.framebuffer(
            () -> "Pipeline-compatible framebuffer target",
            targets
        ));
    }

    private PipelineHandle createPipeline(PipelineDescriptor descriptor, VulkanRenderTargetPlan plan) {
        return createPipeline(descriptor, plan.compatibilityKey(), plan.fragmentRenderTargetInterface());
    }

    private PipelineHandle createPipeline(
        PipelineDescriptor descriptor,
        VulkanRenderPassCompatibilityKey renderPassCompatibilityKey
    ) {
        return createPipeline(descriptor, renderPassCompatibilityKey, null);
    }

    private PipelineHandle createPipeline(
        PipelineDescriptor descriptor,
        VulkanRenderPassCompatibilityKey renderPassCompatibilityKey,
        @Nullable VulkanFragmentRenderTargetInterfacePlanner.RenderTargetInterface renderTargetInterface
    ) {
        descriptor = VulkanShaderVariantPlanner.withCompatibilityVertexInputState(descriptor);
        ensureNativeReady("createPipeline(framebuffer)");
        NativeSpine spine = nativeSpine;
        if (spine == null) {
            throw new IllegalStateException("Native Vulkan spine is unavailable after readiness check.");
        }

        List<VulkanicSpirvModule> spirvModules = descriptor.getSpirvModules();
        if (spirvModules.isEmpty()) {
            throw new IllegalArgumentException(
                "Vulkan pipeline creation requires precompiled SPIR-V shader modules attached to the "
                    + "PipelineDescriptor. Use PipelineDescriptor.fromPortableStateAndSpirvModules(...) "
                    + "or PipelineDescriptor.fromRenderPipelineAndSpirvModules(...) to provide SPIR-V "
                    + "bytecode for both vertex and fragment stages."
            );
        }

        VulkanicSpirvModule vertModule = null;
        VulkanicSpirvModule geomModule = null;
        VulkanicSpirvModule fragModule = null;
        for (VulkanicSpirvModule module : spirvModules) {
            if (module.stage() == VulkanicShaderStage.VERTEX) {
                vertModule = module;
            } else if (module.stage() == VulkanicShaderStage.GEOMETRY) {
                geomModule = module;
            } else if (module.stage() == VulkanicShaderStage.FRAGMENT) {
                fragModule = module;
            }
        }
        if (vertModule == null) {
            throw new IllegalArgumentException(
                "Vulkan pipeline creation requires a VERTEX stage SPIR-V module in the descriptor.");
        }
        if (fragModule == null) {
            throw new IllegalArgumentException(
                "Vulkan pipeline creation requires a FRAGMENT stage SPIR-V module in the descriptor.");
        }

        long vertModuleHandle = spine.createShaderModule(vertModule);
        long geomModuleHandle = geomModule != null ? spine.createShaderModule(geomModule) : VK10.VK_NULL_HANDLE;
        long fragModuleHandle = spine.createShaderModule(fragModule);
        try {
            return spine.createVulkanPipeline(
                descriptor,
                vertModuleHandle,
                geomModuleHandle,
                fragModuleHandle,
                renderPassCompatibilityKey,
                renderTargetInterface
            );
        } finally {
            spine.destroyShaderModule(vertModuleHandle);
            if (geomModuleHandle != VK10.VK_NULL_HANDLE) {
                spine.destroyShaderModule(geomModuleHandle);
            }
            spine.destroyShaderModule(fragModuleHandle);
        }
    }

    public List<VulkanicSpirvModule> getLinkedProgramSpirvModules(CommandContext ctx, int program) {
        requireVulkanCommandBufferHandle("getLinkedProgramSpirvModules", ctx);
        VirtualProgram virtualProgram = shaderPrograms.program(program);
        return virtualProgram == null ? List.of() : virtualProgram.linkedSpirvModules;
    }

    @Nullable
    public PipelineDescriptor.ResourceLayout getLinkedProgramResourceLayout(
        CommandContext ctx,
        int program,
        java.util.Set<VulkanicShaderStage> stages
    ) {
        requireVulkanCommandBufferHandle("getLinkedProgramResourceLayout", ctx);
        LinkedProgramExecutionSnapshot snapshot = shaderPrograms.linkedExecutionSnapshot(program, stages);
        return snapshot == null ? null : snapshot.resourceLayout();
    }

    @Nullable
    private VulkanDrawExecutionCoordinator.LegacyProgramSnapshot requestProgramExecutionSnapshot(
        CommandContext ctx,
        int programId
    ) {
        VirtualProgram virtualProgram = shaderPrograms.program(programId);
        if (virtualProgram == null || !virtualProgram.linkStatus || virtualProgram.linkedSpirvModules.isEmpty()) {
            return null;
        }

        Set<VulkanicShaderStage> stages = virtualProgram.linkedSpirvModules.stream()
            .map(VulkanicSpirvModule::stage)
            .collect(java.util.stream.Collectors.toCollection(java.util.LinkedHashSet::new));
        LinkedProgramExecutionSnapshot snapshot = shaderPrograms.linkedExecutionSnapshot(programId, stages);
        if (snapshot == null) {
            return null;
        }

        return new VulkanDrawExecutionCoordinator.LegacyProgramSnapshot(
            programId,
            snapshot.linkStatus(),
            snapshot.debugLabel(),
            snapshot.linkedSpirvModules(),
            snapshot.vertexInputs().stream()
                .map(input -> new VulkanDrawExecutionCoordinator.ReflectedVertexInputSnapshot(
                    input.location(),
                    input.typeName()
                ))
                .toList(),
            snapshot.attributeLocationsByName(),
            snapshot.resourceLayout(),
            snapshot.activeUniformNames(),
            snapshot.opaqueResourceUniformValuesByIndex()
        );
    }

    @Nullable
    private PipelineDescriptor createLegacyComputePipelineDescriptor(int programId) {
        LinkedProgramExecutionSnapshot snapshot = shaderPrograms.linkedExecutionSnapshot(
            programId,
            Set.of(VulkanicShaderStage.COMPUTE)
        );
        if (snapshot == null || snapshot.linkedSpirvModules().isEmpty()) {
            return null;
        }

        List<VulkanicSpirvModule> computeModules = snapshot.linkedSpirvModules().stream()
            .filter(module -> module.stage() == VulkanicShaderStage.COMPUTE)
            .toList();
        if (computeModules.size() != 1) {
            return null;
        }

        PipelineDescriptor.PortableState portableState = new PipelineDescriptor.PortableState(
            net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vulkanic", "legacy_compute_program/" + programId),
            net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vulkanic", "legacy_compute_program/" + programId + "/compute"),
            net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vulkanic", "legacy_compute_program/" + programId + "/compute"),
            Map.of(),
            Set.of(),
            List.of(),
            List.of(),
            java.util.Optional.empty(),
            net.blaze3d.platform.DepthTestFunction.NO_DEPTH_TEST,
            net.blaze3d.platform.PolygonMode.FILL,
            false,
            VulkanicAPI.GL_BACK,
            false,
            false,
            false,
            net.blaze3d.platform.LogicOp.NONE,
            net.blaze3d.vertex.DefaultVertexFormat.EMPTY,
            VertexFormat.Mode.QUADS,
            0.0F,
            0.0F
        );

        return PipelineDescriptor.fromPortableStateAndSpirvModules(portableState, computeModules)
            .withResourceLayout(snapshot.resourceLayout());
    }

    private PipelineResourcePlanner.Plan buildLegacyProgramResourcePlan(
        CommandContext ctx,
        long commandBufferHandle,
        PipelineDescriptor descriptor,
        int programId
    ) {
        LinkedProgramExecutionSnapshot programSnapshot = shaderPrograms.linkedExecutionSnapshot(
            programId,
            descriptor.getSpirvModules().stream()
                .map(VulkanicSpirvModule::stage)
                .collect(java.util.stream.Collectors.toCollection(java.util.LinkedHashSet::new))
        );
        if (programSnapshot == null) {
            return null;
        }
        return net.vulkanic.VulkanicPipelineResourceResolver.buildPlan(
            ctx,
            descriptor,
            new net.vulkanic.VulkanicPipelineResourceResolver.ResourceLookup() {
                @Override
                @Nullable
                public VulkanicTextureView samplerView(PipelineDescriptor.ResourceBinding binding) {
                    Integer unit = samplerUnit(binding);
                    if (unit == null) {
                        return null;
                    }
                    NativeSpine spine = nativeSpine;
                    int textureId = 0;
                    if (spine != null) {
                        textureId = spine.textureResources.boundLegacyTexture2D(unit);
                    }
                    if (textureId <= 0) {
                        textureId = net.irisshaders.iris.gl.IrisRenderSystem.getTextureBinding(unit);
                    }
                    VulkanicTextureView textureView = textureId > 0 ? createManagedLegacyTextureView(textureId) : null;
                    return textureView != null
                        ? textureView
                        : createLegacyFallbackSamplerView(commandBufferHandle, binding, unit);
                }

                @Override
                @Nullable
                public Integer samplerUnit(PipelineDescriptor.ResourceBinding binding) {
                    return VulkanShaderProgramCoordinator.samplerOrImageUnit(
                        programSnapshot.activeUniformNames(),
                        programSnapshot.opaqueResourceUniformValuesByIndex(),
                        binding
                    );
                }

                @Override
                @Nullable
                public VulkanicBufferSlice uniformBufferSlice(PipelineDescriptor.ResourceBinding binding) {
                    return null;
                }

                @Override
                @Nullable
                public Integer texelBufferUnit(PipelineDescriptor.ResourceBinding binding) {
                    return samplerUnit(binding);
                }

                @Override
                @Nullable
                public PipelineResourceBindings.StorageImageBinding storageImageBinding(PipelineDescriptor.ResourceBinding binding) {
                    return resolveLegacyStorageImageBindingForSnapshot(programSnapshot, binding);
                }

                @Override
                @Nullable
                public Integer standaloneProgramId(PipelineDescriptor.ResourceBinding binding) {
                    return programId;
                }

                @Override
                @Nullable
                public Integer samplerObject(int samplerUnit) {
                    Integer samplerObject = textureResources.boundSampler(samplerUnit);
                    return samplerObject != null && samplerObject > 0 ? samplerObject : null;
                }
            },
            PipelineResourcePlanner.options()
                .requireAtLeastOneBinding(false)
                .filterIncompleteLayout(false)
        );
    }

    private VulkanCompactResourceBindingTable buildSharedProgramResourceTable(
        CommandContext ctx,
        long commandBufferHandle,
        PipelineDescriptor descriptor,
        VulkanDrawExecutionCoordinator.LegacyProgramSnapshot programSnapshot,
        VulkanicCompatibilityState.GraphicsSnapshot sharedSnapshot
    ) {
        if (programSnapshot == null) {
            return null;
        }
        return legacyResourcePlanTemplate(descriptor, programSnapshot)
            .resolveCompact(ctx, commandBufferHandle, descriptor, programSnapshot, sharedSnapshot);
    }

    private VulkanCompactResourceBindingTable buildExplicitV2ProgramResourceTable(
        CommandContext ctx,
        long commandBufferHandle,
        PipelineDescriptor descriptor,
        VulkanDrawExecutionCoordinator.LegacyProgramSnapshot programSnapshot,
        VulkanicGalV2.ResourceSet resourceSet
    ) {
        if (programSnapshot == null) {
            return null;
        }
        return galV2ResourcePlanTemplate(descriptor, programSnapshot, resourceSet.layout())
            .resolveCompact(ctx, commandBufferHandle, descriptor, programSnapshot, resourceSet);
    }

    private LegacyResourcePlanTemplate galV2ResourcePlanTemplate(
        PipelineDescriptor descriptor,
        VulkanDrawExecutionCoordinator.LegacyProgramSnapshot programSnapshot,
        VulkanicGalV2.Handle resourceLayout
    ) {
        GalV2ResourcePlanTemplateKey key = new GalV2ResourcePlanTemplateKey(
            programSnapshot.programId(),
            descriptor.getStableCacheKey(),
            descriptor.getResourceLayoutCacheKey(),
            resourceLayout
        );
        if (MAX_LEGACY_RESOURCE_PLAN_TEMPLATE_CACHE_ENTRIES <= 0) {
            return createLegacyResourcePlanTemplate(descriptor, programSnapshot);
        }
        synchronized (galV2ResourcePlanTemplateCache) {
            LegacyResourcePlanTemplate cached = galV2ResourcePlanTemplateCache.get(key);
            if (cached != null) {
                VulkanPerfAudit.recordLegacyGraphicsLoweringCacheLookup(
                    descriptor.getPortableState().location().toString(),
                    "gal_v2_resource_plan_template",
                    true,
                    galV2ResourcePlanTemplateCache.size(),
                    galV2ResourcePlanTemplateCacheHighWater
                );
                return cached;
            }
        }

        LegacyResourcePlanTemplate created = createLegacyResourcePlanTemplate(descriptor, programSnapshot);
        synchronized (galV2ResourcePlanTemplateCache) {
            if (galV2ResourcePlanTemplateCache.size() >= MAX_LEGACY_RESOURCE_PLAN_TEMPLATE_CACHE_ENTRIES) {
                java.util.Iterator<GalV2ResourcePlanTemplateKey> iterator = galV2ResourcePlanTemplateCache.keySet().iterator();
                if (iterator.hasNext()) {
                    iterator.next();
                    iterator.remove();
                }
            }
            galV2ResourcePlanTemplateCache.put(key, created);
            galV2ResourcePlanTemplateCacheHighWater =
                Math.max(galV2ResourcePlanTemplateCacheHighWater, galV2ResourcePlanTemplateCache.size());
            VulkanPerfAudit.recordLegacyGraphicsLoweringCacheLookup(
                descriptor.getPortableState().location().toString(),
                "gal_v2_resource_plan_template",
                false,
                galV2ResourcePlanTemplateCache.size(),
                galV2ResourcePlanTemplateCacheHighWater
            );
        }
        return created;
    }

    private LegacyResourcePlanTemplate legacyResourcePlanTemplate(
        PipelineDescriptor descriptor,
        VulkanDrawExecutionCoordinator.LegacyProgramSnapshot programSnapshot
    ) {
        long keyStartNanos = VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
        LegacyResourcePlanTemplateKey key = new LegacyResourcePlanTemplateKey(
            descriptor.getResourceLayout(),
            programSnapshot.programId(),
            programSnapshot.activeUniformNames(),
            programSnapshot.opaqueResourceUniformValuesByIndex()
        );
        recordLegacyGraphicsLoweringStep(
            descriptor.getPortableState().location().toString(),
            "resource_plan.hashing_key_creation",
            keyStartNanos
        );
        if (MAX_LEGACY_RESOURCE_PLAN_TEMPLATE_CACHE_ENTRIES <= 0) {
            return createLegacyResourcePlanTemplate(descriptor, programSnapshot);
        }
        synchronized (legacyResourcePlanTemplateCache) {
            LegacyResourcePlanTemplate cached = legacyResourcePlanTemplateCache.get(key);
            if (cached != null) {
                VulkanPerfAudit.recordLegacyGraphicsLoweringCacheLookup(
                    descriptor.getPortableState().location().toString(),
                    "resource_plan_template",
                    true,
                    legacyResourcePlanTemplateCache.size(),
                    legacyResourcePlanTemplateCacheHighWater
                );
                return cached;
            }
        }

        LegacyResourcePlanTemplate created = createLegacyResourcePlanTemplate(descriptor, programSnapshot);
        synchronized (legacyResourcePlanTemplateCache) {
            legacyResourcePlanTemplateCache.put(key, created);
            while (legacyResourcePlanTemplateCache.size() > MAX_LEGACY_RESOURCE_PLAN_TEMPLATE_CACHE_ENTRIES) {
                java.util.Iterator<LegacyResourcePlanTemplateKey> iterator = legacyResourcePlanTemplateCache.keySet().iterator();
                if (!iterator.hasNext()) {
                    break;
                }
                iterator.next();
                iterator.remove();
            }
            legacyResourcePlanTemplateCacheHighWater =
                Math.max(legacyResourcePlanTemplateCacheHighWater, legacyResourcePlanTemplateCache.size());
            VulkanPerfAudit.recordLegacyGraphicsLoweringCacheLookup(
                descriptor.getPortableState().location().toString(),
                "resource_plan_template",
                false,
                legacyResourcePlanTemplateCache.size(),
                legacyResourcePlanTemplateCacheHighWater
            );
        }
        return created;
    }

    private LegacyResourcePlanTemplate createLegacyResourcePlanTemplate(
        PipelineDescriptor descriptor,
        VulkanDrawExecutionCoordinator.LegacyProgramSnapshot programSnapshot
    ) {
        long classificationStartNanos = VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
        List<LegacyResourceBindingTemplate> bindings = new ArrayList<>(descriptor.getResourceLayout().bindings().size());
        for (PipelineDescriptor.ResourceBinding binding : descriptor.getResourceLayout().bindings()) {
            Integer resourceUnit = switch (binding.type()) {
                case SAMPLER, COMPARISON_SAMPLER, STORAGE_IMAGE, TEXEL_BUFFER ->
                    VulkanShaderProgramCoordinator.samplerOrImageUnit(
                        programSnapshot.activeUniformNames(),
                        programSnapshot.opaqueResourceUniformValuesByIndex(),
                        binding
                    );
                case UNIFORM_BUFFER -> null;
            };
            bindings.add(new LegacyResourceBindingTemplate(
                binding,
                resourceUnit,
                binding.type() == PipelineDescriptor.ResourceType.UNIFORM_BUFFER
                    && VulkanicAPI.generatedStandaloneUniformBlockName().equals(binding.name())
            ));
        }
        recordLegacyGraphicsLoweringStep(
            descriptor.getPortableState().location().toString(),
            "resource_plan.resource_classification",
            classificationStartNanos
        );
        return new LegacyResourcePlanTemplate(bindings);
    }

    private void invalidateLegacyResourcePlanTemplatesForProgram(int programId, String reason) {
        if (programId <= 0) {
            return;
        }
        int removed = 0;
        if (MAX_LEGACY_RESOURCE_PLAN_TEMPLATE_CACHE_ENTRIES > 0) {
            synchronized (legacyResourcePlanTemplateCache) {
                java.util.Iterator<LegacyResourcePlanTemplateKey> iterator = legacyResourcePlanTemplateCache.keySet().iterator();
                while (iterator.hasNext()) {
                    LegacyResourcePlanTemplateKey key = iterator.next();
                    if (key.programId() == programId) {
                        iterator.remove();
                        removed++;
                    }
                }
            }
            synchronized (galV2ResourcePlanTemplateCache) {
                java.util.Iterator<GalV2ResourcePlanTemplateKey> iterator = galV2ResourcePlanTemplateCache.keySet().iterator();
                while (iterator.hasNext()) {
                    GalV2ResourcePlanTemplateKey key = iterator.next();
                    if (key.programId() == programId) {
                        iterator.remove();
                        removed++;
                    }
                }
            }
        }
        if (MAX_LEGACY_PROGRAM_PIPELINE_KEY_CACHE_ENTRIES > 0) {
            synchronized (legacyProgramPipelineKeyCache) {
                java.util.Iterator<LegacyProgramPipelineKeyCacheKey> iterator = legacyProgramPipelineKeyCache.keySet().iterator();
                while (iterator.hasNext()) {
                    LegacyProgramPipelineKeyCacheKey key = iterator.next();
                    if (key.programId() == programId) {
                        iterator.remove();
                        removed++;
                    }
                }
            }
        }
        if (removed > 0) {
            VulkanPerfAudit.recordLegacyGraphicsLoweringCacheInvalidation(reason, removed);
        }
    }

    private final class LegacyResourcePlanTemplate {
        private final LegacyResourceBindingTemplate[] bindings;
        private final PipelineDescriptor.ResourceBinding[] layoutBindings;
        private final int samplerBindingCount;
        private final int uniformBufferBindingCount;
        private final int storageImageBindingCount;
        private final int texelBufferBindingCount;

        private LegacyResourcePlanTemplate(List<LegacyResourceBindingTemplate> bindings) {
            this.bindings = bindings.toArray(LegacyResourceBindingTemplate[]::new);
            this.layoutBindings = new PipelineDescriptor.ResourceBinding[this.bindings.length];
            int samplers = 0;
            int uniformBuffers = 0;
            int storageImages = 0;
            int texelBuffers = 0;
            for (int index = 0; index < this.bindings.length; index++) {
                LegacyResourceBindingTemplate template = this.bindings[index];
                this.layoutBindings[index] = template.binding();
                switch (template.binding().type()) {
                    case SAMPLER, COMPARISON_SAMPLER -> samplers++;
                    case UNIFORM_BUFFER -> uniformBuffers++;
                    case STORAGE_IMAGE -> storageImages++;
                    case TEXEL_BUFFER -> texelBuffers++;
                }
            }
            this.samplerBindingCount = samplers;
            this.uniformBufferBindingCount = uniformBuffers;
            this.storageImageBindingCount = storageImages;
            this.texelBufferBindingCount = texelBuffers;
        }

        private VulkanCompactResourceBindingTable resolveCompact(
            CommandContext ctx,
            long commandBufferHandle,
            PipelineDescriptor descriptor,
            VulkanDrawExecutionCoordinator.LegacyProgramSnapshot programSnapshot,
            VulkanicCompatibilityState.GraphicsSnapshot sharedSnapshot
        ) {
            String pipelineLocation = descriptor.getPortableState().location().toString();
            long traversalStartNanos = VulkanPerfAudit.shouldTraceLegacyGraphicsLowering() ? System.nanoTime() : 0L;
            int layoutBindingCount = bindings.length;
            Object[] resourceBindingSlots = new Object[layoutBindingCount];
            int boundResourceCount = 0;
            int missingResourceCount = 0;
            ResourcePlanResolveMetrics metrics = new ResourcePlanResolveMetrics();
            recordLegacyGraphicsLoweringStep(
                pipelineLocation,
                "resource_plan.compatibility_snapshot_traversal",
                traversalStartNanos
            );

            int slotIndex = 0;
            for (LegacyResourceBindingTemplate template : bindings) {
                PipelineDescriptor.ResourceBinding binding = template.binding();
                Object resourceBinding = null;
                switch (binding.type()) {
                    case SAMPLER, COMPARISON_SAMPLER -> {
                        PipelineResourceBindings.SamplerBinding samplerBinding =
                            resolveTemplateSamplerBinding(commandBufferHandle, binding, template.resourceUnit(), sharedSnapshot, metrics);
                        if (samplerBinding != null) {
                            resourceBinding = samplerBinding;
                            boundResourceCount++;
                        } else {
                            missingResourceCount++;
                        }
                    }
                    case UNIFORM_BUFFER -> {
                        long uniformLookupStartNanos =
                            VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
                        VulkanicBufferSlice uniformBufferBinding = template.generatedStandaloneUniformBlock()
                            ? VulkanicAPI.getStandaloneUniformBufferSlice(ctx, programSnapshot.programId())
                            : null;
                        if (uniformLookupStartNanos != 0L) {
                            metrics.uniformBufferLookupNanos += System.nanoTime() - uniformLookupStartNanos;
                        }
                        if (uniformBufferBinding != null) {
                            resourceBinding = uniformBufferBinding;
                            boundResourceCount++;
                        } else {
                            missingResourceCount++;
                        }
                    }
                    case STORAGE_IMAGE -> {
                        PipelineResourceBindings.StorageImageBinding imageBinding =
                            resolveTemplateStorageImageBinding(template.resourceUnit(), sharedSnapshot.imageUnitBindings());
                        if (imageBinding != null) {
                            long canonicalStartNanos = VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
                            VulkanicPassResourceModel.CanonicalResourceReference reference =
                                storageImageReferenceFor(binding, imageBinding);
                            if (canonicalStartNanos != 0L) {
                                metrics.canonicalReferenceNanos += System.nanoTime() - canonicalStartNanos;
                            }
                            resourceBinding = imageBinding.withResourceReference(reference);
                            boundResourceCount++;
                        } else {
                            missingResourceCount++;
                        }
                    }
                    case TEXEL_BUFFER -> {
                        Integer textureUnit = template.resourceUnit();
                        if (textureUnit != null) {
                            resourceBinding = new PipelineResourceBindings.TexelBufferBinding(textureUnit);
                            boundResourceCount++;
                        } else {
                            missingResourceCount++;
                        }
                    }
                }
                resourceBindingSlots[slotIndex] = resourceBinding;
                slotIndex++;
            }
            recordResourcePlanResolveMetrics(pipelineLocation, metrics);
            recordLegacyGraphicsLoweringAllocation(
                pipelineLocation,
                "VulkanCompactResourceBindingTable",
                1L + (layoutBindingCount == 0 ? 0L : 1L),
                80L + 8L * layoutBindingCount
            );

            boolean completeCoverage = boundResourceCount == layoutBindingCount;
            recordLegacyGraphicsLoweringAllocation(
                pipelineLocation,
                "VulkanCompactResourceBindingPlan",
                1L,
                48L + (missingResourceCount == 0 ? 0L : 32L + 32L * missingResourceCount)
            );
            return new VulkanCompactResourceBindingTable(
                descriptor,
                layoutBindings,
                resourceBindingSlots,
                boundResourceCount,
                missingResourceCount
            );
        }

        private VulkanCompactResourceBindingTable resolveCompact(
            CommandContext ctx,
            long commandBufferHandle,
            PipelineDescriptor descriptor,
            VulkanDrawExecutionCoordinator.LegacyProgramSnapshot programSnapshot,
            VulkanicGalV2.ResourceSet resourceSet
        ) {
            String pipelineLocation = descriptor.getPortableState().location().toString();
            long traversalStartNanos = VulkanPerfAudit.shouldTraceLegacyGraphicsLowering() ? System.nanoTime() : 0L;
            int layoutBindingCount = bindings.length;
            Object[] resourceBindingSlots = new Object[layoutBindingCount];
            int boundResourceCount = 0;
            int missingResourceCount = 0;
            ResourcePlanResolveMetrics metrics = new ResourcePlanResolveMetrics();
            recordLegacyGraphicsLoweringStep(
                pipelineLocation,
                "resource_plan.v2_resource_set_traversal",
                traversalStartNanos
            );

            int slotIndex = 0;
            for (LegacyResourceBindingTemplate template : bindings) {
                PipelineDescriptor.ResourceBinding binding = template.binding();
                Object resourceBinding = null;
                switch (binding.type()) {
                    case SAMPLER, COMPARISON_SAMPLER -> {
                        PipelineResourceBindings.SamplerBinding samplerBinding =
                            resolveTemplateSamplerBinding(commandBufferHandle, binding, template.resourceUnit(), resourceSet, metrics);
                        if (samplerBinding != null) {
                            resourceBinding = samplerBinding;
                            boundResourceCount++;
                        } else {
                            missingResourceCount++;
                        }
                    }
                    case UNIFORM_BUFFER -> {
                        Object uniformBinding = template.generatedStandaloneUniformBlock()
                            ? resolveTemplateStandaloneUniformBinding(programSnapshot.programId(), binding.name(), resourceSet)
                            : resolveTemplateUniformBufferBinding(binding.name(), resourceSet);
                        if (uniformBinding != null) {
                            resourceBinding = uniformBinding;
                            boundResourceCount++;
                        } else {
                            missingResourceCount++;
                        }
                    }
                    case STORAGE_IMAGE -> {
                        PipelineResourceBindings.StorageImageBinding imageBinding =
                            resolveTemplateStorageImageBinding(template.resourceUnit(), resourceSet);
                        if (imageBinding != null) {
                            resourceBinding = imageBinding;
                            boundResourceCount++;
                        } else {
                            missingResourceCount++;
                        }
                    }
                    case TEXEL_BUFFER -> {
                        Integer textureUnit = template.resourceUnit();
                        if (textureUnit != null) {
                            VulkanicGalV2.ResourceBinding bindingReference =
                                resourceSet.sampledTextureBindingOrNull(textureUnit);
                            VulkanicPassResourceModel.CanonicalResourceReference reference =
                                bindingReference == null ? null : bindingReference.resourceReference().orElse(null);
                            resourceBinding = new PipelineResourceBindings.TexelBufferBinding(textureUnit, reference);
                            boundResourceCount++;
                        } else {
                            missingResourceCount++;
                        }
                    }
                }
                resourceBindingSlots[slotIndex] = resourceBinding;
                slotIndex++;
            }
            recordResourcePlanResolveMetrics(pipelineLocation, metrics);
            recordLegacyGraphicsLoweringAllocation(
                pipelineLocation,
                "VulkanCompactResourceBindingTable",
                1L + (layoutBindingCount == 0 ? 0L : 1L),
                80L + 8L * layoutBindingCount
            );
            recordLegacyGraphicsLoweringAllocation(
                pipelineLocation,
                "VulkanCompactResourceBindingPlan",
                1L,
                48L + (missingResourceCount == 0 ? 0L : 32L + 32L * missingResourceCount)
            );
            return new VulkanCompactResourceBindingTable(
                descriptor,
                layoutBindings,
                resourceBindingSlots,
                boundResourceCount,
                missingResourceCount
            );
        }

        @Nullable
        private VulkanStandaloneUniformBinding resolveTemplateStandaloneUniformBinding(
            int programId,
            String bindingName,
            VulkanicGalV2.ResourceSet resourceSet
        ) {
            VulkanicGalV2.ResourceBinding requestBinding = resourceSet.uniformBindingOrNull(bindingName);
            if (requestBinding == null || requestBinding.uniformBinding().isEmpty()) {
                return null;
            }
            VulkanicGalV2.Handle handle = requestBinding.uniformBinding().orElseThrow();
            VulkanicGalV2.UniformBinding uniformBinding = VulkanicGalV2.requireUniformBinding(handle);
            if (uniformBinding.programId() != programId || !uniformBinding.bindingName().equals(bindingName)) {
                throw new IllegalStateException(
                    "Mismatched GAL v2 uniform binding for " + bindingName
                        + ": expected program="
                        + programId
                        + " actual="
                        + uniformBinding);
            }
            return new VulkanStandaloneUniformBinding(programId, bindingName, handle);
        }

        @Nullable
        private VulkanicBufferSlice resolveTemplateUniformBufferBinding(
            String bindingName,
            VulkanicGalV2.ResourceSet resourceSet
        ) {
            VulkanicGalV2.ResourceBinding requestBinding = resourceSet.bufferRangeBindingOrNull(bindingName);
            if (requestBinding == null || requestBinding.resourceReference().isEmpty()) {
                return null;
            }
            VulkanicPassResourceModel.CanonicalResourceReference reference =
                requestBinding.resourceReference().orElseThrow();
            if (reference.resource().kind() != VulkanicPassResourceModel.ResourceKind.UNIFORM_BUFFER
                || reference.legacyId().isEmpty()) {
                return null;
            }
            VulkanBuffer buffer = nativeSpine.resolveLegacyVulkanBuffer(reference.legacyId().getAsInt());
            if (buffer == null) {
                return null;
            }
            long offset = reference.subresource().baseMipLevel();
            long size = reference.subresource().levelCount();
            if (offset < 0L || size < 0L || offset > Integer.MAX_VALUE || size > Integer.MAX_VALUE) {
                throw new IllegalArgumentException("Unsupported GAL v2 uniform buffer range for " + bindingName
                    + ": offset=" + offset + " size=" + size);
            }
            return new VulkanicBufferSlice(buffer, (int) offset, (int) size);
        }

        @Nullable
        private PipelineResourceBindings.SamplerBinding resolveTemplateSamplerBinding(
            long commandBufferHandle,
            PipelineDescriptor.ResourceBinding binding,
            @Nullable Integer unit,
            VulkanicCompatibilityState.GraphicsSnapshot sharedSnapshot,
            ResourcePlanResolveMetrics metrics
        ) {
            if (unit == null) {
                return null;
            }

            long lookupStartNanos = VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
            int textureId = sharedTextureIdForSampler(
                sharedSnapshot.textureUnitBindings(),
                sharedSnapshot.textureBindingsByKey(),
                binding,
                unit
            );
            Integer samplerObject = sharedSnapshot.samplerBindings().get(unit);
            samplerObject = samplerObject != null && samplerObject > 0 ? samplerObject : null;
            if (lookupStartNanos != 0L) {
                metrics.samplerImageBufferLookupNanos += System.nanoTime() - lookupStartNanos;
            }

            long fallbackStartNanos = VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
            VulkanicTextureView textureView = textureId > 0 ? createManagedLegacyTextureView(textureId) : null;
            if (textureView == null) {
                textureView = createLegacyFallbackSamplerView(commandBufferHandle, binding, unit);
            }
            if (fallbackStartNanos != 0L) {
                metrics.fallbackSelectionNanos += System.nanoTime() - fallbackStartNanos;
            }
            if (textureView == null) {
                return null;
            }

            long canonicalStartNanos = VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
            VulkanicPassResourceModel.CanonicalResourceReference reference = textureId > 0
                ? sharedSamplerReferenceForTextureId(
                    binding,
                    unit,
                    textureView,
                    textureId,
                    sharedSnapshot.textureUnitBindings(),
                    sharedSnapshot.textureBindingsByKey(),
                    sharedSnapshot.samplerBindings()
                )
                : null;
            if (canonicalStartNanos != 0L) {
                metrics.canonicalReferenceNanos += System.nanoTime() - canonicalStartNanos;
            }

            long entryStartNanos = VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
            PipelineResourceBindings.SamplerBinding samplerBinding =
                new PipelineResourceBindings.SamplerBinding(unit, samplerObject, textureView, reference);
            if (entryStartNanos != 0L) {
                metrics.descriptorEntryConstructionNanos += System.nanoTime() - entryStartNanos;
            }
            return samplerBinding;
        }

        @Nullable
        private PipelineResourceBindings.SamplerBinding resolveTemplateSamplerBinding(
            long commandBufferHandle,
            PipelineDescriptor.ResourceBinding binding,
            @Nullable Integer unit,
            VulkanicGalV2.ResourceSet resourceSet,
            ResourcePlanResolveMetrics metrics
        ) {
            if (unit == null) {
                return null;
            }
            VulkanicGalV2.ResourceBinding requestBinding =
                resourceSet.sampledTextureBindingOrNull(unit);
            VulkanicPassResourceModel.CanonicalResourceReference reference =
                requestBinding == null ? null : requestBinding.resourceReference().orElse(null);
            int textureId = reference != null && reference.legacyId().isPresent()
                ? reference.legacyId().getAsInt()
                : 0;
            Integer samplerObject = reference != null && reference.samplerObject().isPresent()
                ? reference.samplerObject().getAsInt()
                : null;

            long fallbackStartNanos = VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
            VulkanicTextureView textureView = textureId > 0 ? createManagedLegacyTextureView(textureId) : null;
            if (textureView == null) {
                textureView = createLegacyFallbackSamplerView(commandBufferHandle, binding, unit);
            }
            if (fallbackStartNanos != 0L) {
                metrics.fallbackSelectionNanos += System.nanoTime() - fallbackStartNanos;
            }
            if (textureView == null) {
                return null;
            }

            long entryStartNanos = VulkanPerfAudit.shouldTraceResourcePlanBreakdown() ? System.nanoTime() : 0L;
            PipelineResourceBindings.SamplerBinding samplerBinding =
                new PipelineResourceBindings.SamplerBinding(unit, samplerObject, textureView, reference);
            if (entryStartNanos != 0L) {
                metrics.descriptorEntryConstructionNanos += System.nanoTime() - entryStartNanos;
            }
            return samplerBinding;
        }

        @Nullable
        private PipelineResourceBindings.StorageImageBinding resolveTemplateStorageImageBinding(
            @Nullable Integer imageUnit,
            Map<Integer, VulkanicCompatibilityState.ImageUnitBindingState> imageUnitBindings
        ) {
            if (imageUnit == null) {
                return null;
            }
            VulkanicCompatibilityState.ImageUnitBindingState imageBinding = imageUnitBindings.get(imageUnit);
            return imageBinding == null
                ? null
                : new PipelineResourceBindings.StorageImageBinding(
                    imageBinding.imageUnit(),
                    imageBinding.texture(),
                    imageBinding.level(),
                    imageBinding.layered(),
                    imageBinding.layer(),
                    imageBinding.access(),
                    imageBinding.format()
                );
        }

        @Nullable
        private PipelineResourceBindings.StorageImageBinding resolveTemplateStorageImageBinding(
            @Nullable Integer imageUnit,
            VulkanicGalV2.ResourceSet resourceSet
        ) {
            if (imageUnit == null) {
                return null;
            }
            VulkanicGalV2.ResourceBinding requestBinding =
                resourceSet.storageImageBindingOrNull(imageUnit);
            if (requestBinding == null || requestBinding.resourceReference().isEmpty()) {
                return null;
            }
            VulkanicPassResourceModel.CanonicalResourceReference reference =
                requestBinding.resourceReference().orElseThrow();
            if (reference.legacyId().isEmpty()) {
                return null;
            }
            int level = reference.subresource().baseMipLevel();
            int layer = reference.subresource().baseLayer();
            return new PipelineResourceBindings.StorageImageBinding(
                imageUnit,
                reference.legacyId().getAsInt(),
                level,
                reference.layered(),
                layer,
                reference.imageAccess().orElse(VulkanicAPI.GL_READ_WRITE),
                reference.imageFormat().orElse(VulkanicAPI.GL_RGBA8),
                reference
            );
        }
    }

    private static List<String> appendMissingResource(@Nullable List<String> missingResources, String entry) {
        List<String> resources = missingResources;
        if (resources == null) {
            resources = new ArrayList<>();
        }
        resources.add(entry);
        return resources;
    }

    @SafeVarargs
    private static int nonEmptyMapCount(Map<?, ?>... maps) {
        int count = 0;
        for (Map<?, ?> map : maps) {
            if (!map.isEmpty()) {
                count++;
            }
        }
        return count;
    }

    private static long estimatedPipelineResourceBindingBytes(
        int samplerBindings,
        int uniformBufferBindings,
        int storageImageBindings,
        int texelBufferBindings
    ) {
        int totalBindings = samplerBindings + uniformBufferBindings + storageImageBindings + texelBufferBindings;
        long mapBytes = 48L * nonEmptyCount(samplerBindings, uniformBufferBindings, storageImageBindings, texelBufferBindings);
        long nodeBytes = 40L * totalBindings;
        long bindingBytes =
            40L * samplerBindings
                + 24L * uniformBufferBindings
                + 48L * storageImageBindings
                + 24L * texelBufferBindings;
        return 64L + mapBytes + nodeBytes + bindingBytes;
    }

    private static int nonEmptyCount(int... counts) {
        int nonEmpty = 0;
        for (int count : counts) {
            if (count > 0) {
                nonEmpty++;
            }
        }
        return nonEmpty;
    }

    private static void recordResourcePlanResolveMetrics(String pipelineLocation, ResourcePlanResolveMetrics metrics) {
        if (!VulkanPerfAudit.shouldTraceResourcePlanBreakdown()) {
            return;
        }
        if (metrics.samplerImageBufferLookupNanos > 0L) {
            VulkanPerfAudit.recordLegacyGraphicsLoweringStep(
                pipelineLocation,
                "resource_plan.sampler_image_buffer_lookup",
                metrics.samplerImageBufferLookupNanos
            );
        }
        if (metrics.fallbackSelectionNanos > 0L) {
            VulkanPerfAudit.recordLegacyGraphicsLoweringStep(
                pipelineLocation,
                "resource_plan.fallback_selection",
                metrics.fallbackSelectionNanos
            );
        }
        if (metrics.canonicalReferenceNanos > 0L) {
            VulkanPerfAudit.recordLegacyGraphicsLoweringStep(
                pipelineLocation,
                "resource_plan.canonical_reference_creation",
                metrics.canonicalReferenceNanos
            );
        }
        if (metrics.uniformBufferLookupNanos > 0L) {
            VulkanPerfAudit.recordLegacyGraphicsLoweringStep(
                pipelineLocation,
                "resource_plan.uniform_buffer_lookup",
                metrics.uniformBufferLookupNanos
            );
        }
        if (metrics.descriptorEntryConstructionNanos > 0L) {
            VulkanPerfAudit.recordLegacyGraphicsLoweringStep(
                pipelineLocation,
                "resource_plan.descriptor_entry_construction",
                metrics.descriptorEntryConstructionNanos
            );
        }
    }

    private static final class ResourcePlanResolveMetrics {
        private long samplerImageBufferLookupNanos;
        private long fallbackSelectionNanos;
        private long canonicalReferenceNanos;
        private long uniformBufferLookupNanos;
        private long descriptorEntryConstructionNanos;
    }

    private record LegacyResourcePlanTemplateKey(
        PipelineDescriptor.ResourceLayout resourceLayout,
        int programId,
        List<String> activeUniformNames,
        Map<Integer, Integer> opaqueResourceUniformValuesByIndex
    ) {
        private LegacyResourcePlanTemplateKey {
            Objects.requireNonNull(resourceLayout, "resourceLayout");
            Objects.requireNonNull(activeUniformNames, "activeUniformNames");
            Objects.requireNonNull(opaqueResourceUniformValuesByIndex, "opaqueResourceUniformValuesByIndex");
        }
    }

    private record LegacyResourceBindingTemplate(
        PipelineDescriptor.ResourceBinding binding,
        @Nullable Integer resourceUnit,
        boolean generatedStandaloneUniformBlock
    ) {
        private LegacyResourceBindingTemplate {
            Objects.requireNonNull(binding, "binding");
        }
    }

    private PipelineResourcePlanner.Plan buildSharedProgramResourcePlan(
        CommandContext ctx,
        long commandBufferHandle,
        PipelineDescriptor descriptor,
        int programId,
        VulkanicCompatibilityState.ComputeSnapshot sharedSnapshot
    ) {
        LinkedProgramExecutionSnapshot programSnapshot = shaderPrograms.linkedExecutionSnapshot(
            programId,
            descriptor.getSpirvModules().stream()
                .map(VulkanicSpirvModule::stage)
                .collect(java.util.stream.Collectors.toCollection(java.util.LinkedHashSet::new))
        );
        if (programSnapshot == null) {
            return null;
        }
        return net.vulkanic.VulkanicPipelineResourceResolver.buildPlan(
            ctx,
            descriptor,
            new net.vulkanic.VulkanicPipelineResourceResolver.ResourceLookup() {
                @Override
                @Nullable
                public VulkanicTextureView samplerView(PipelineDescriptor.ResourceBinding binding) {
                    Integer unit = samplerUnit(binding);
                    if (unit == null) {
                        return null;
                    }
                    int textureId = sharedTextureIdForSampler(
                        sharedSnapshot.textureUnitBindings(),
                        sharedSnapshot.textureBindingsByKey(),
                        binding,
                        unit
                    );
                    VulkanicTextureView textureView = textureId > 0 ? createManagedLegacyTextureView(textureId) : null;
                    return textureView != null
                        ? textureView
                        : createLegacyFallbackSamplerView(commandBufferHandle, binding, unit);
                }

                @Override
                @Nullable
                public Integer samplerUnit(PipelineDescriptor.ResourceBinding binding) {
                    return VulkanShaderProgramCoordinator.samplerOrImageUnit(
                        programSnapshot.activeUniformNames(),
                        programSnapshot.opaqueResourceUniformValuesByIndex(),
                        binding
                    );
                }

                @Override
                @Nullable
                public VulkanicBufferSlice uniformBufferSlice(PipelineDescriptor.ResourceBinding binding) {
                    return null;
                }

                @Override
                @Nullable
                public Integer texelBufferUnit(PipelineDescriptor.ResourceBinding binding) {
                    return samplerUnit(binding);
                }

                @Override
                @Nullable
                public PipelineResourceBindings.StorageImageBinding storageImageBinding(PipelineDescriptor.ResourceBinding binding) {
                    return resolveSharedStorageImageBinding(programSnapshot, binding, sharedSnapshot.imageUnitBindings());
                }

                @Override
                @Nullable
                public Integer standaloneProgramId(PipelineDescriptor.ResourceBinding binding) {
                    return programId;
                }

                @Override
                @Nullable
                public Integer samplerObject(int samplerUnit) {
                    Integer samplerObject = sharedSnapshot.samplerBindings().get(samplerUnit);
                    return samplerObject != null && samplerObject > 0 ? samplerObject : null;
                }

                @Override
                @Nullable
                public VulkanicPassResourceModel.CanonicalResourceReference samplerReference(
                    PipelineDescriptor.ResourceBinding binding,
                    int samplerUnit,
                    VulkanicTextureView textureView
                ) {
                    return sharedSamplerReference(
                        binding,
                        samplerUnit,
                        textureView,
                        sharedSnapshot.textureUnitBindings(),
                        sharedSnapshot.textureBindingsByKey(),
                        sharedSnapshot.samplerBindings()
                    );
                }

                @Override
                @Nullable
                public VulkanicPassResourceModel.CanonicalResourceReference storageImageReference(
                    PipelineDescriptor.ResourceBinding binding,
                    PipelineResourceBindings.StorageImageBinding imageBinding
                ) {
                    return storageImageReferenceFor(binding, imageBinding);
                }
            },
            PipelineResourcePlanner.options()
                .requireAtLeastOneBinding(false)
                .filterIncompleteLayout(false)
        );
    }

    @Nullable
    PipelineResourceBindings.StorageImageBinding resolveLegacyStorageImageBindingForProgram(
        int programId,
        PipelineDescriptor.ResourceBinding binding
    ) {
        LinkedProgramExecutionSnapshot snapshot = shaderPrograms.linkedExecutionSnapshot(programId, binding.stages());
        if (snapshot == null) {
            return null;
        }
        return resolveLegacyStorageImageBindingForSnapshot(snapshot, binding);
    }

    @Nullable
    private PipelineResourceBindings.StorageImageBinding resolveLegacyStorageImageBindingForSnapshot(
        LinkedProgramExecutionSnapshot snapshot,
        PipelineDescriptor.ResourceBinding binding
    ) {
        int imageUnit = VulkanShaderProgramCoordinator.samplerOrImageUnit(
            snapshot.activeUniformNames(),
            snapshot.opaqueResourceUniformValuesByIndex(),
            binding
        );
        NativeSpine spine = nativeSpine;
        if (spine == null) {
            return null;
        }
        LegacyImageBinding imageBinding = spine.textureResources.legacyImageBinding(imageUnit);
        return imageBinding == null
            ? null
            : new PipelineResourceBindings.StorageImageBinding(
                imageBinding.imageUnit(),
                imageBinding.texture(),
                imageBinding.level(),
                imageBinding.layered(),
                imageBinding.layer(),
                imageBinding.access(),
                imageBinding.format()
            );
    }

    @Nullable
    private static PipelineResourceBindings.StorageImageBinding resolveSharedStorageImageBinding(
        VulkanDrawExecutionCoordinator.LegacyProgramSnapshot snapshot,
        PipelineDescriptor.ResourceBinding binding,
        Map<Integer, VulkanicCompatibilityState.ImageUnitBindingState> imageUnitBindings
    ) {
        int imageUnit = VulkanShaderProgramCoordinator.samplerOrImageUnit(
            snapshot.activeUniformNames(),
            snapshot.opaqueResourceUniformValuesByIndex(),
            binding
        );
        VulkanicCompatibilityState.ImageUnitBindingState imageBinding = imageUnitBindings.get(imageUnit);
        return imageBinding == null
            ? null
            : new PipelineResourceBindings.StorageImageBinding(
                imageBinding.imageUnit(),
                imageBinding.texture(),
                imageBinding.level(),
                imageBinding.layered(),
                imageBinding.layer(),
                imageBinding.access(),
                imageBinding.format()
            );
    }

    @Nullable
    private static PipelineResourceBindings.StorageImageBinding resolveSharedStorageImageBinding(
        LinkedProgramExecutionSnapshot snapshot,
        PipelineDescriptor.ResourceBinding binding,
        Map<Integer, VulkanicCompatibilityState.ImageUnitBindingState> imageUnitBindings
    ) {
        int imageUnit = VulkanShaderProgramCoordinator.samplerOrImageUnit(
            snapshot.activeUniformNames(),
            snapshot.opaqueResourceUniformValuesByIndex(),
            binding
        );
        VulkanicCompatibilityState.ImageUnitBindingState imageBinding = imageUnitBindings.get(imageUnit);
        return imageBinding == null
            ? null
            : new PipelineResourceBindings.StorageImageBinding(
                imageBinding.imageUnit(),
                imageBinding.texture(),
                imageBinding.level(),
                imageBinding.layered(),
                imageBinding.layer(),
                imageBinding.access(),
                imageBinding.format()
            );
    }

    private static int sharedTextureIdForSampler(
        Map<Integer, Integer> textureUnitBindings,
        Map<VulkanicCompatibilityState.TextureBindingKey, Integer> textureBindings,
        PipelineDescriptor.ResourceBinding binding,
        int unit
    ) {
        int directTexture = textureUnitBindings.getOrDefault(unit, 0);
        if (directTexture > 0) {
            return directTexture;
        }
        int texture2D = textureBindings.getOrDefault(
            new VulkanicCompatibilityState.TextureBindingKey(unit, VulkanicAPI.GL_TEXTURE_2D),
            0
        );
        int texture3D = textureBindings.getOrDefault(
            new VulkanicCompatibilityState.TextureBindingKey(unit, VulkanicAPI.GL_TEXTURE_3D),
            0
        );
        if (texture3D > 0 && knownIris3DSampler(binding.name())) {
            return texture3D;
        }
        if (texture2D > 0) {
            return texture2D;
        }
        if (texture3D > 0) {
            return texture3D;
        }
        for (Map.Entry<VulkanicCompatibilityState.TextureBindingKey, Integer> entry : textureBindings.entrySet()) {
            if (entry.getKey().unit() == unit && entry.getValue() != null && entry.getValue() > 0) {
                return entry.getValue();
            }
        }
        return 0;
    }

    @Nullable
    private static VulkanicPassResourceModel.CanonicalResourceReference sharedSamplerReference(
        PipelineDescriptor.ResourceBinding binding,
        int unit,
        VulkanicTextureView textureView,
        Map<Integer, Integer> textureUnitBindings,
        Map<VulkanicCompatibilityState.TextureBindingKey, Integer> textureBindings,
        Map<Integer, Integer> samplerBindings
    ) {
        int textureId = sharedTextureIdForSampler(textureUnitBindings, textureBindings, binding, unit);
        if (textureId <= 0) {
            return null;
        }
        return sharedSamplerReferenceForTextureId(
            binding,
            unit,
            textureView,
            textureId,
            textureUnitBindings,
            textureBindings,
            samplerBindings
        );
    }

    private static VulkanicPassResourceModel.CanonicalResourceReference sharedSamplerReferenceForTextureId(
        PipelineDescriptor.ResourceBinding binding,
        int unit,
        VulkanicTextureView textureView,
        int textureId,
        Map<Integer, Integer> textureUnitBindings,
        Map<VulkanicCompatibilityState.TextureBindingKey, Integer> textureBindings,
        Map<Integer, Integer> samplerBindings
    ) {
        OptionalInt target = sharedTextureTargetForSampler(textureUnitBindings, textureBindings, binding, unit, textureId);
        int baseMip = Math.max(0, textureView.getBaseMipLevel());
        int mipCount = Math.max(1, textureView.getMipLevelCount());
        return VulkanicPassResourceModel.CanonicalResourceReference.sampledTexture(
            binding.name(),
            "legacy-texture:" + textureId,
            textureId,
            target,
            target.isPresent()
                ? targetClassForLegacyTarget(target.getAsInt())
                : VulkanicPassResourceModel.TargetClass.UNKNOWN,
            VulkanicPassResourceModel.Subresource.color(baseMip, mipCount, 0, 1),
            OptionalInt.of(unit),
            samplerBindings.getOrDefault(unit, 0) > 0
                ? OptionalInt.of(samplerBindings.get(unit))
                : OptionalInt.empty()
        );
    }

    private static OptionalInt sharedTextureTargetForSampler(
        Map<Integer, Integer> textureUnitBindings,
        Map<VulkanicCompatibilityState.TextureBindingKey, Integer> textureBindings,
        PipelineDescriptor.ResourceBinding binding,
        int unit,
        int textureId
    ) {
        if (textureUnitBindings.getOrDefault(unit, 0) == textureId) {
            return OptionalInt.empty();
        }
        VulkanicCompatibilityState.TextureBindingKey texture2D =
            new VulkanicCompatibilityState.TextureBindingKey(unit, VulkanicAPI.GL_TEXTURE_2D);
        VulkanicCompatibilityState.TextureBindingKey texture3D =
            new VulkanicCompatibilityState.TextureBindingKey(unit, VulkanicAPI.GL_TEXTURE_3D);
        if (textureBindings.getOrDefault(texture3D, 0) == textureId && knownIris3DSampler(binding.name())) {
            return OptionalInt.of(VulkanicAPI.GL_TEXTURE_3D);
        }
        if (textureBindings.getOrDefault(texture2D, 0) == textureId) {
            return OptionalInt.of(VulkanicAPI.GL_TEXTURE_2D);
        }
        if (textureBindings.getOrDefault(texture3D, 0) == textureId) {
            return OptionalInt.of(VulkanicAPI.GL_TEXTURE_3D);
        }
        for (Map.Entry<VulkanicCompatibilityState.TextureBindingKey, Integer> entry : textureBindings.entrySet()) {
            if (entry.getKey().unit() == unit && entry.getValue() == textureId) {
                return OptionalInt.of(entry.getKey().target());
            }
        }
        return OptionalInt.empty();
    }

    private static VulkanicPassResourceModel.TargetClass targetClassForLegacyTarget(int target) {
        return switch (target) {
            case VulkanicAPI.GL_TEXTURE_2D -> VulkanicPassResourceModel.TargetClass.TEXTURE_2D;
            case VulkanicAPI.GL_TEXTURE_3D -> VulkanicPassResourceModel.TargetClass.TEXTURE_3D;
            default -> VulkanicPassResourceModel.TargetClass.UNKNOWN;
        };
    }

    private static VulkanicPassResourceModel.CanonicalResourceReference storageImageReferenceFor(
        PipelineDescriptor.ResourceBinding binding,
        PipelineResourceBindings.StorageImageBinding imageBinding
    ) {
        VulkanicPassResourceModel.Access access = switch (imageBinding.access()) {
            case LEGACY_GL_READ_ONLY -> VulkanicPassResourceModel.Access.READ;
            case LEGACY_GL_WRITE_ONLY -> VulkanicPassResourceModel.Access.WRITE;
            default -> VulkanicPassResourceModel.Access.READ_WRITE;
        };
        VulkanicResourceUsage usage = imageBinding.access() == LEGACY_GL_READ_ONLY
            ? VulkanicResourceUsage.SAMPLED_READ
            : VulkanicResourceUsage.STORAGE_READ_WRITE;
        return VulkanicPassResourceModel.CanonicalResourceReference.storageImage(
            binding.name(),
            "legacy-texture:" + imageBinding.texture(),
            imageBinding.texture(),
            imageBinding.level(),
            imageBinding.layered(),
            imageBinding.layer(),
            access,
            usage,
            OptionalInt.of(imageBinding.imageUnit()),
            OptionalInt.of(imageBinding.access()),
            OptionalInt.of(imageBinding.format())
        );
    }

    private static boolean knownIris3DSampler(String name) {
        return "voxel_sampler".equals(name)
            || "floodfill_sampler".equals(name)
            || "floodfill_sampler_copy".equals(name);
    }

    private static net.blaze3d.platform.LogicOp legacyLogicOp(int opcode) {
        return opcode == 0x150B /* GL_OR_REVERSE */
            ? net.blaze3d.platform.LogicOp.OR_REVERSE
            : net.blaze3d.platform.LogicOp.NONE;
    }

    @Nullable
    Integer resolveLegacySamplerUnitForProgram(int programId, PipelineDescriptor.ResourceBinding binding) {
        LinkedProgramExecutionSnapshot snapshot = shaderPrograms.linkedExecutionSnapshot(programId, binding.stages());
        if (snapshot == null) {
            return null;
        }

        int uniformIndex = snapshot.activeUniformNames().indexOf(binding.name());
        if (uniformIndex >= 0) {
            Integer uploadedUnit = snapshot.opaqueResourceUniformValuesByIndex().get(uniformIndex);
            if (uploadedUnit != null) {
                return uploadedUnit;
            }
        }

        Integer aliasedUnit = resolveLegacySamplerAliasUnit(snapshot, binding.name());
        if (aliasedUnit != null) {
            return aliasedUnit;
        }

        Integer defaultUnit = defaultLegacySamplerUnit(binding.name());
        return defaultUnit != null ? defaultUnit : binding.binding();
    }

    @Nullable
    private static Integer resolveLegacySamplerAliasUnit(LinkedProgramExecutionSnapshot snapshot, String bindingName) {
        for (String aliasName : legacySamplerAliasNames(bindingName)) {
            int aliasIndex = snapshot.activeUniformNames().indexOf(aliasName);
            Integer uploadedUnit = aliasIndex < 0 ? null : snapshot.opaqueResourceUniformValuesByIndex().get(aliasIndex);
            if (uploadedUnit != null) {
                return uploadedUnit;
            }
        }

        return null;
    }

    static List<String> legacySamplerAliasNames(String bindingName) {
        return switch (bindingName) {
            case "Sampler0" -> List.of("tex", "gtexture", "texture");
            case "Sampler1" -> List.of("iris_overlay", "overlay");
            case "Sampler2" -> List.of("lightmap", "iris_lightmap", "gaux2");
            default -> List.of();
        };
    }

    @Nullable
    static Integer defaultLegacySamplerUnit(String bindingName) {
        return switch (bindingName) {
            case "Sampler0" -> 0;
            case "Sampler1" -> 1;
            case "Sampler2" -> 2;
            default -> null;
        };
    }

    @Nullable
    VulkanicTextureView resolveLegacySamplerViewForProgram(
        CommandContext ctx,
        PipelineDescriptor.ResourceBinding binding,
        int programId
    ) {
        long commandBufferHandle = requireVulkanCommandBufferHandle("resolveLegacySamplerViewForProgram", ctx);
        Integer unit = resolveLegacySamplerUnitForProgram(programId, binding);
        if (unit == null) {
            return null;
        }

        NativeSpine spine = nativeSpine;
        int textureId = 0;
        if (spine != null) {
            textureId = spine.textureResources.boundLegacyTexture2D(unit);
        }
        if (textureId <= 0) {
            textureId = net.irisshaders.iris.gl.IrisRenderSystem.getTextureBinding(unit);
        }
        VulkanicTextureView textureView = null;
        if (textureId > 0) {
            net.blaze3d.textures.GpuTextureView trackedTextureView =
                net.irisshaders.iris.pbr.TextureTracker.INSTANCE.getTextureView(textureId);
            if (trackedTextureView != null && trackedTextureView.texture() instanceof VulkanicTexture trackedTexture) {
                textureView = createManagedTextureView(
                    trackedTexture,
                    trackedTextureView.baseMipLevel(),
                    trackedTextureView.mipLevels()
                );
            }
            if (textureView == null) {
                textureView = createManagedLegacyTextureView(textureId);
            }
        }
        return textureView != null
            ? textureView
            : createLegacyFallbackSamplerView(commandBufferHandle, binding, unit);
    }

    @Nullable
    private VulkanicTextureView createLegacyFallbackSamplerView(
        long commandBufferHandle,
        PipelineDescriptor.ResourceBinding binding,
        int samplerUnit
    ) {
        NativeSpine spine = nativeSpine;
        if (spine == null) {
            return null;
        }
        int target = fallbackSamplerTarget(binding);
        if (!spine.canEnsureLegacyFallbackSamplerTexture(commandBufferHandle, target)) {
            return null;
        }

        int fallbackTextureId = spine.ensureLegacyFallbackSamplerTexture(commandBufferHandle, target);
        VulkanicTextureView fallbackView = createManagedLegacyTextureView(fallbackTextureId);
        if (fallbackView != null) {
            String key = binding.name() + '|' + samplerUnit;
            if (LEGACY_FALLBACK_SAMPLER_LOGS.add(key)) {
                LOGGER.warn(
                    "Binding Vulkan legacy sampler '{}' on unit {} to the backend fallback black texture target=0x{} because no legacy texture is bound.",
                    binding.name(),
                    samplerUnit,
                    Integer.toHexString(target)
                );
            }
        }
        return fallbackView;
    }

    private static int fallbackSamplerTarget(PipelineDescriptor.ResourceBinding binding) {
        return knownIris3DSampler(binding.name())
            ? VulkanicAPI.GL_TEXTURE_3D
            : VulkanicAPI.GL_TEXTURE_2D;
    }

    private static void logIncompleteLegacyResourcePlan(
        String operation,
        int programId,
        PipelineResourcePlanner.Plan resourcePlan
    ) {
        String missing = String.join(", ", resourcePlan.missingResources());
        String key = operation + '|' + programId + '|' + missing;
        if (LEGACY_INCOMPLETE_RESOURCE_PLAN_LOGS.add(key)) {
            LOGGER.warn(
                "Skipping Vulkan legacy {} for program {} because required reflected resources are not bound: {}",
                operation,
                programId,
                missing.isBlank() ? "<unknown>" : missing
            );
        }
    }

    private static void logIncompleteLegacyResourceTable(
        String operation,
        int programId,
        VulkanCompactResourceBindingTable resourceTable
    ) {
        String missing = String.join(", ", resourceTable.missingResources());
        String key = operation + '|' + programId + '|' + missing;
        if (LEGACY_INCOMPLETE_RESOURCE_PLAN_LOGS.add(key)) {
            LOGGER.warn(
                "Skipping Vulkan legacy {} for program {} because required reflected resources are not bound: {}",
                operation,
                programId,
                missing.isBlank() ? "<unknown>" : missing
            );
        }
    }

    @Nullable
    private MaterializedGraphicsPipelineBinding materializeLegacyProgramPipelineForDraw(
        long commandBufferHandle,
        VulkanDrawExecutionCoordinator.DrawExecutionPlan drawPlan,
        List<VulkanicPassResourceModel.ResourceUse> capturedUses,
        @Nullable VulkanCompactResourceBindingTable capturedResourceBindingTable
    ) {
        Objects.requireNonNull(capturedUses, "capturedUses");
        boolean missingDrawUse = drawPlan.resourcePlan().orderedUses().stream()
            .anyMatch(use -> !containsEquivalentResourceUse(capturedUses, use));
        if (missingDrawUse) {
            throw new IllegalStateException(
                "Captured GAL resource plan no longer matches Vulkan draw execution plan. missing="
                    + missingCapturedResourceUses(capturedUses, drawPlan)
            );
        }
        int programId = drawPlan.programId();
        if (drawPlan.descriptor() == null) {
            return null;
        }
        PipelineDescriptor descriptor = drawPlan.descriptor();
        String pipelineLocation = descriptor.getPortableState().location().toString();

        VulkanCompactResourceBindingTable resourceTable = capturedResourceBindingTable;
        if (resourceTable == null) {
            return null;
        }
        if (!resourceTable.completeCoverage()) {
            logIncompleteLegacyResourceTable("draw", programId, resourceTable);
            return null;
        }

        ensureNativeReady("materializeLegacyProgramPipelineForDraw");
        NativeSpine spine = nativeSpine;
        if (spine == null) {
            throw new IllegalStateException("Native Vulkan spine is unavailable after readiness check.");
        }

        long compatibilityStartNanos = VulkanPerfAudit.shouldTraceLegacyGraphicsLowering() ? System.nanoTime() : 0L;
        int framebuffer = framebufferRenderTargets.boundDrawFramebuffer();
        VulkanRenderPassCompatibilityKey compatibilityKey = spine.activeRenderPassCompatibilityKey();
        if (compatibilityKey == null && framebuffer != 0) {
            ResolvedFramebufferTargets targets = resolveFramebufferTargets(framebuffer);
            compatibilityKey = VulkanRenderPassCompatibilityKey.framebuffer(
                targets.colorFormats(),
                targets.hasDepthTarget() ? targets.depthTexture.vkFormat : VK10.VK_FORMAT_UNDEFINED,
                targets.hasFeedbackLoopTarget()
            );
        } else if (compatibilityKey == null) {
            compatibilityKey = defaultRenderPassCompatibilityKey();
        }
        recordLegacyGraphicsLoweringStep(pipelineLocation, "render_target_compatibility_resolve", compatibilityStartNanos);

        PipelineDescriptor submissionDescriptor = resourceTable.descriptor();
        long pipelineKeyStartNanos = VulkanPerfAudit.shouldTraceLegacyGraphicsLowering() ? System.nanoTime() : 0L;
        LegacyProgramPipelineKey key = legacyProgramPipelineKey(programId, submissionDescriptor, compatibilityKey, pipelineLocation);
        recordLegacyGraphicsLoweringStep(pipelineLocation, "pipeline_cache_key_build", pipelineKeyStartNanos);

        long pipelineLookupStartNanos = VulkanPerfAudit.shouldTraceLegacyGraphicsLowering() ? System.nanoTime() : 0L;
        PipelineHandle pipelineHandle = pipelineLifecycle.getCachedPipeline(
            VulkanPipelineLifecycleManager.CacheKind.LEGACY_PROGRAM,
            key
        );
        boolean pipelineCacheHit = pipelineHandle != null;
        recordLegacyGraphicsLoweringStep(pipelineLocation, "pipeline_cache_lookup", pipelineLookupStartNanos);
        if (pipelineHandle == null) {
            long pipelineMaterializeStartNanos = VulkanPerfAudit.shouldTraceLegacyGraphicsLowering() ? System.nanoTime() : 0L;
            PipelineHandle created = createPipeline(submissionDescriptor, compatibilityKey);
            recordLegacyGraphicsLoweringStep(pipelineLocation, "pipeline_materialization", pipelineMaterializeStartNanos);
            pipelineHandle = pipelineLifecycle.cachePipeline(
                VulkanPipelineLifecycleManager.CacheKind.LEGACY_PROGRAM,
                key,
                created
            );
        }
        VulkanPerfAudit.recordLegacyGraphicsLoweringCacheLookup(
            pipelineLocation,
            "native_pipeline",
            pipelineCacheHit,
            pipelineLifecycle.cachedPipelineCount(VulkanPipelineLifecycleManager.CacheKind.LEGACY_PROGRAM),
            pipelineLifecycle.cachedPipelineCount(VulkanPipelineLifecycleManager.CacheKind.LEGACY_PROGRAM)
        );
        if (pipelineHandle == null || !pipelineHandle.isValid()) {
            return null;
        }

        if (!(pipelineHandle instanceof VulkanPipelineHandle vulkanPipeline)) {
            return null;
        }
        long descriptorMaterializeStartNanos = VulkanPerfAudit.shouldTraceLegacyGraphicsLowering() ? System.nanoTime() : 0L;
        try {
            return spine.materializeGraphicsPipelineBinding(
                commandBufferHandle,
                vulkanPipeline,
                submissionDescriptor,
                resourceTable
            );
        } finally {
            recordLegacyGraphicsLoweringStep(pipelineLocation, "descriptor_materialization", descriptorMaterializeStartNanos);
        }
    }

    private LegacyProgramPipelineKey legacyProgramPipelineKey(
        int programId,
        PipelineDescriptor descriptor,
        VulkanRenderPassCompatibilityKey compatibilityKey,
        String pipelineLocation
    ) {
        if (MAX_LEGACY_PROGRAM_PIPELINE_KEY_CACHE_ENTRIES <= 0) {
            recordLegacyGraphicsLoweringAllocation(pipelineLocation, "LegacyProgramPipelineKey", 2L, 96L);
            return new LegacyProgramPipelineKey(normalizedGraphicsPipelineCacheKey(descriptor, compatibilityKey));
        }
        LegacyProgramPipelineKeyCacheKey cacheKey =
            new LegacyProgramPipelineKeyCacheKey(programId, descriptor, compatibilityKey);
        synchronized (legacyProgramPipelineKeyCache) {
            LegacyProgramPipelineKey cached = legacyProgramPipelineKeyCache.get(cacheKey);
            if (cached != null) {
                VulkanPerfAudit.recordLegacyGraphicsLoweringCacheLookup(
                    pipelineLocation,
                    "legacy_program_pipeline_key",
                    true,
                    legacyProgramPipelineKeyCache.size(),
                    legacyProgramPipelineKeyCacheHighWater
                );
                return cached;
            }
        }

        LegacyProgramPipelineKey created =
            new LegacyProgramPipelineKey(normalizedGraphicsPipelineCacheKey(descriptor, compatibilityKey));
        recordLegacyGraphicsLoweringAllocation(pipelineLocation, "LegacyProgramPipelineKey", 2L, 96L);
        synchronized (legacyProgramPipelineKeyCache) {
            legacyProgramPipelineKeyCache.put(cacheKey, created);
            while (legacyProgramPipelineKeyCache.size() > MAX_LEGACY_PROGRAM_PIPELINE_KEY_CACHE_ENTRIES) {
                java.util.Iterator<LegacyProgramPipelineKeyCacheKey> iterator = legacyProgramPipelineKeyCache.keySet().iterator();
                if (!iterator.hasNext()) {
                    break;
                }
                iterator.next();
                iterator.remove();
            }
            legacyProgramPipelineKeyCacheHighWater =
                Math.max(legacyProgramPipelineKeyCacheHighWater, legacyProgramPipelineKeyCache.size());
            VulkanPerfAudit.recordLegacyGraphicsLoweringCacheLookup(
                pipelineLocation,
                "legacy_program_pipeline_key",
                false,
                legacyProgramPipelineKeyCache.size(),
                legacyProgramPipelineKeyCacheHighWater
            );
        }
        return created;
    }

    private static String missingCapturedResourceUses(
        List<VulkanicPassResourceModel.ResourceUse> capturedUses,
        VulkanDrawExecutionCoordinator.DrawExecutionPlan drawPlan
    ) {
        return drawPlan.resourcePlan().orderedUses().stream()
            .filter(use -> !containsEquivalentResourceUse(capturedUses, use))
            .limit(8)
            .map(use -> use.resource().stableKey()
                + "/" + use.kind()
                + "/" + use.access()
                + "/role=" + use.role()
                + "/sub=" + use.subresource()
                + "/capturedSameKey=[" + capturedUses.stream()
                    .filter(captured -> captured.resource().stableKey().equals(use.resource().stableKey()))
                    .limit(4)
                    .map(captured -> captured.kind()
                        + "/" + captured.access()
                        + "/role=" + captured.role()
                        + "/sub=" + captured.subresource())
                    .collect(java.util.stream.Collectors.joining(", "))
                + "]")
            .collect(java.util.stream.Collectors.joining("; "));
    }

    private static boolean containsEquivalentResourceUse(
        List<VulkanicPassResourceModel.ResourceUse> uses,
        VulkanicPassResourceModel.ResourceUse expected
    ) {
        return uses.stream().anyMatch(actual ->
            actual.resource().stableKey().equals(expected.resource().stableKey())
                && actual.kind() == expected.kind()
                && actual.access() == expected.access()
                && actual.subresource().equals(expected.subresource())
                && actual.usage() == expected.usage()
                && actual.role().equals(expected.role())
                && actual.feedbackLoop() == expected.feedbackLoop()
        );
    }

    private static VulkanResourceUsageExecutionPlanner.ExecutionPlan consumeResourceUsagePlan(
        VulkanicPassResourceModel.PassExecutionPlan resourcePlan
    ) {
        return VulkanResourceUsageExecutionPlanner.plan(resourcePlan);
    }

    private PipelineResourcePlanner.Plan requestOwnedComputeResourceBindingPlan(
        CommandContext ctx,
        long commandBufferHandle,
        VulkanicGalExecutionRequest.ComputeDispatchRequest request
    ) {
        VulkanicCompatibilityState.ComputeSnapshot sharedSnapshot =
            request.compatibilitySnapshot().sharedCompatibilityState()
                .orElseThrow(() -> new IllegalStateException(
                    "Vulkan compute execution received a GAL request without a shared immutable compatibility snapshot: "
                        + request.semanticIdentity().label()));
        int programId = sharedSnapshot.programId();
        if (programId <= 0) {
            throw new IllegalStateException("Vulkan compute execution requires a captured compute program");
        }
        PipelineDescriptor descriptor = createLegacyComputePipelineDescriptor(programId);
        if (descriptor == null) {
            throw new IllegalStateException("No valid Vulkan compute pipeline descriptor is available for captured program " + programId);
        }
        return buildSharedProgramResourcePlan(ctx, commandBufferHandle, descriptor, programId, sharedSnapshot);
    }

    @Nullable
    private MaterializedComputePipelineBinding materializeLegacyComputePipelineForDispatch(
        long commandBufferHandle,
        VulkanicGalExecutionRequest.ComputeDispatchRequest capturedRequest,
        PipelineResourcePlanner.Plan requestOwnedResourcePlan
    ) {
        if (capturedRequest.compatibilitySnapshot().sharedCompatibilityState().isEmpty()) {
            throw new IllegalStateException("Vulkan compute execution received a GAL request without captured shared compatibility state");
        }
        PipelineResourcePlanner.Plan resourcePlan = Objects.requireNonNull(requestOwnedResourcePlan, "requestOwnedResourcePlan");
        if (!resourcePlan.completeCoverage()) {
            logIncompleteLegacyResourcePlan("dispatch", -1, resourcePlan);
            return null;
        }

        ensureNativeReady("materializeLegacyComputePipelineForDispatch");
        NativeSpine spine = nativeSpine;
        if (spine == null) {
            throw new IllegalStateException("Native Vulkan spine is unavailable after readiness check.");
        }

        PipelineDescriptor submissionDescriptor = resourcePlan.descriptor();
        LegacyComputePipelineKey key = new LegacyComputePipelineKey(
            normalizedComputePipelineCacheKey(submissionDescriptor)
        );
        PipelineHandle pipelineHandle = pipelineLifecycle.getCachedPipeline(
            VulkanPipelineLifecycleManager.CacheKind.LEGACY_COMPUTE,
            key
        );
        if (pipelineHandle == null) {
            VulkanicSpirvModule computeModule = submissionDescriptor.getSpirvModules().stream()
                .filter(module -> module.stage() == VulkanicShaderStage.COMPUTE)
                .findFirst()
                .orElseThrow(() -> new IllegalStateException("Compute descriptor has no COMPUTE SPIR-V module."));
            long computeModuleHandle = spine.createShaderModule(computeModule);
            try {
                PipelineHandle created = spine.createVulkanComputePipeline(submissionDescriptor, computeModuleHandle);
                pipelineHandle = pipelineLifecycle.cachePipeline(
                    VulkanPipelineLifecycleManager.CacheKind.LEGACY_COMPUTE,
                    key,
                    created
                );
            } finally {
                spine.destroyShaderModule(computeModuleHandle);
            }
        }
        if (!(pipelineHandle instanceof VulkanPipelineHandle vulkanPipeline) || !vulkanPipeline.isValid()) {
            return null;
        }

        return spine.materializeComputePipelineBinding(
            commandBufferHandle,
            vulkanPipeline,
            submissionDescriptor,
            resourcePlan.bindings()
        );
    }

