    private void dispatchCompute(CommandContext ctx, int workX, int workY, int workZ) {
        executeComputeDispatch(ctx, VulkanicGalExecutionRequest.ComputeDispatchRequest.direct(
            "dispatchCompute",
            workX,
            workY,
            workZ
        ));
    }

    public VulkanicGalExecutionRequest.ExecutionResult executeComputeDispatch(CommandContext ctx, VulkanicGalExecutionRequest.ComputeDispatchRequest request) {
        long auditStartNanos = VulkanPerfAudit.isEnabled() ? System.nanoTime() : 0L;
        try {
            Objects.requireNonNull(request, "request");
            consumeResourceUsagePlan(request.resourcePlan());
            VulkanicGalExecutionRequest.ComputeDispatchCommand command = request.command();
            if (command.indirect()) {
                dispatchComputeIndirectLegacy(ctx, request);
            } else {
                executeTypedComputeDispatchPlan(ctx, request);
            }
            return VulkanicGalExecutionRequest.success(request.semanticIdentity());
        } catch (RuntimeException exception) {
            return VulkanicGalExecutionRequest.backendFailure(request.semanticIdentity(), exception.getMessage());
        } finally {
            if (auditStartNanos != 0L) {
                VulkanPerfAudit.recordPhase("backend.vulkan.compute", System.nanoTime() - auditStartNanos);
            }
        }
    }

    private void executeTypedComputeDispatchPlan(
        CommandContext ctx,
        VulkanicGalExecutionRequest.ComputeDispatchRequest request
    ) {
        long commandBufferHandle = requireVulkanCommandBufferHandle("dispatchCompute", ctx);
        VulkanicGalExecutionRequest.ComputeDispatchCommand command = request.command();
        int workX = command.workX();
        int workY = command.workY();
        int workZ = command.workZ();
        if (workX <= 0 || workY <= 0 || workZ <= 0) {
            return;
        }
        NativeSpine spine = nativeSpine;
        if (spine == null) {
            throw new IllegalStateException("Native Vulkan spine is unavailable for dispatchCompute.");
        }
        if (spine.isRenderPassRecording()) {
            throw new IllegalStateException("Cannot dispatch Vulkan compute while a render pass is active.");
        }
        PipelineResourcePlanner.Plan requestOwnedResourcePlan =
            requestOwnedComputeResourceBindingPlan(ctx, commandBufferHandle, request);
        MaterializedComputePipelineBinding materialized =
            materializeLegacyComputePipelineForDispatch(commandBufferHandle, request, requestOwnedResourcePlan);
        if (materialized == null) {
            throw new IllegalStateException("No valid Vulkan compute pipeline is bound for dispatchCompute.");
        }
        spine.executeComputeDispatch(
            commandBufferHandle,
            materialized,
            VulkanComputeCommandExecutionCoordinator.ComputeDispatchRequirement.direct(
                request.semanticIdentity().label(),
                workX,
                workY,
                workZ
            )
        );
    }

    private void dispatchComputeIndirect(CommandContext ctx, long offset) {
        executeComputeDispatch(ctx, VulkanicGalExecutionRequest.ComputeDispatchRequest.indirect(
            "dispatchComputeIndirect",
            offset
        ));
    }

    private void dispatchComputeIndirectLegacy(
        CommandContext ctx,
        VulkanicGalExecutionRequest.ComputeDispatchRequest request
    ) {
        long commandBufferHandle = requireVulkanCommandBufferHandle("dispatchComputeIndirect", ctx);
        long offset = request.command().indirectOffset();
        NativeSpine spine = nativeSpine;
        if (spine == null) {
            throw new IllegalStateException("Native Vulkan spine is unavailable for dispatchComputeIndirect.");
        }
        if (spine.isRenderPassRecording()) {
            throw new IllegalStateException("Cannot dispatch Vulkan compute while a render pass is active.");
        }
        PipelineResourcePlanner.Plan requestOwnedResourcePlan =
            requestOwnedComputeResourceBindingPlan(ctx, commandBufferHandle, request);
        MaterializedComputePipelineBinding materialized =
            materializeLegacyComputePipelineForDispatch(commandBufferHandle, request, requestOwnedResourcePlan);
        if (materialized == null) {
            throw new IllegalStateException("No valid Vulkan compute pipeline is bound for dispatchComputeIndirect.");
        }
        int bufferId = request.compatibilitySnapshot().sharedCompatibilityState()
            .map(snapshot -> snapshot.bufferBindings().getOrDefault(VulkanicAPI.GL_DISPATCH_INDIRECT_BUFFER, 0))
            .orElse(0);
        if (bufferId == 0) {
            throw new IllegalStateException("dispatchComputeIndirect requires a GL_DISPATCH_INDIRECT_BUFFER binding.");
        }
        VulkanBufferVertexResourceManager.BufferStorageSnapshot bufferObject =
            bufferVertexResources.requireLegacyBufferSnapshot(bufferId);
        VulkanBuffer indirectBuffer = bufferObject.buffer();
        if (indirectBuffer == null || indirectBuffer.isClosed()) {
            throw new IllegalStateException("dispatchComputeIndirect buffer " + bufferId + " has no Vulkan buffer storage.");
        }
        spine.executeComputeDispatch(
            commandBufferHandle,
            materialized,
            VulkanComputeCommandExecutionCoordinator.ComputeDispatchRequirement.indirect(
                "dispatchComputeIndirect",
                indirectBuffer.getVkBufferHandle(),
                offset
            )
        );
    }

