    private static String mapPciVendorName(int vendorId) {
        return switch (vendorId) {
            case 0x10DE -> "NVIDIA";
            case 0x1002, 0x1022 -> "AMD";
            case 0x8086 -> "Intel";
            case 0x13B5 -> "ARM";
            case 0x5143 -> "Qualcomm";
            case 0x1010 -> "Imagination";
            case 0x106B -> "Apple";
            default -> "Vulkanic";
        };
    }

